export const WIRE_SHAPES_BY_ID: ReadonlyMap<number, ShapeContract> = new Map(WIRE_SHAPES.map((s) => [s.id, s]));
export function wireShape(id: number): ShapeContract { const s = WIRE_SHAPES_BY_ID.get(id); if (!s) throw new Error('unknown-shape'); return s; }
export function readWire(buffer: ArrayBuffer, id: number, expected: ExpectedReply = {}): DecodedReply { return decodeReply(buffer, wireShape(id), expected, WIRE_SHAPES_BY_ID); }
export function readSharedDiagnostics(buffer: ArrayBuffer, expected: ExpectedReply = {}): DecodedReply { return readWire(buffer, 1, expected); }
